		SRCSINK, DEFAULT, CUSTOM
	}

	public enum TaskType {
		SET_TAINT, SET_DELTA, APPLY_DELTA
	}

	public static TaintState newInstance(TaintPlugin plugin, string type) {
		List<Class<TaintState>> list = ClassSearcher.getClasses(typeof(TaintState))
				.stream()
				.toList();
		Class<object>[] constructorArgumentTypes = {typeof(TaintPlugin)};
		object[] args = new object[1];
		args[0] = plugin;
		foreach (Class<TaintState> clazz in list) {
			if (clazz.getName().toLowerCase().contains(type)) {
				try {
					Constructor<object> constructor = clazz.getConstructor(constructorArgumentTypes);
					object obj = constructor.newInstance(plugin);
					return typeof(TaintState).cast(obj);
				}
				catch (Exception e) {
					throw new RuntimeException("Unable to instantiate TaintState");
				}
			}
		}
		Msg.error(plugin, "No match for engine = "+type);
		return null;
	}

